export * as RadioGroup from './group.ts';
export * as Radio from './radio.ts';
export type {
  RadioOwnProps,
  RadioProps,
  RootOwnProps as RadioGroupRootOwnProps,
  RootProps as RadioGroupRootProps,
} from './radio-group.tsx';

@layer hj.components {
  /* Customise: --hj-radio-size · --hj-radio-group-gap */
  .hj-radio-group {
    display: flex;
    flex-direction: column;
    gap: var(--hj-radio-group-gap, 2px);
    font-family: var(--hj-font-sans);
  }
  .hj-radio-group[data-orientation='horizontal'] {
    flex-direction: row;
    flex-wrap: wrap;
    gap: var(--hj-radio-group-gap, var(--hj-space-2) var(--hj-space-6));
  }
  .hj-radio-group-item {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    min-height: var(--hj-touch);
    padding-block: 11px;
    font: var(--hj-type-body);
    letter-spacing: var(--hj-tracking-body);
    color: var(--hj-fg);
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
  }
  .hj-radio-group-item:has([data-disabled]) {
    color: var(--hj-fg-mute);
    cursor: not-allowed;
  }
  .hj-radio-group-description {
    display: block;
    margin-top: 2px;
    font: var(--hj-type-sub);
    color: var(--hj-fg-mute);
  }

  .hj-radio-group-radio {
    --_s: var(--hj-radio-size, 22px);
    position: relative;
    display: inline-grid;
    flex: none;
    place-items: center;
    width: var(--_s);
    height: var(--_s);
    margin-top: -1px;
    border-radius: 50%;
    background: var(--hj-surface);
    box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--hj-fg) 26%, transparent);
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    transition:
      box-shadow var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy) var(--hj-ease-snappy);
  }
  .hj-radio-group-radio::before {
    content: '';
    position: absolute;
    inset: calc((var(--_s) - var(--hj-touch)) / 2);
    border-radius: 50%;
  }
  .hj-radio-group-radio[data-size='sm'] {
    --_s: var(--hj-radio-size, 18px);
  }
  .hj-radio-group-radio:hover:not([data-disabled]):not([data-checked]) {
    box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--hj-fg) 44%, transparent);
  }
  .hj-radio-group-radio:active:not([data-disabled]) {
    transform: scale(0.92);
    transition-duration: var(--hj-dur-fast), 70ms;
  }
  /* hanji: a 2px accent ring around a dot half the diameter */
  .hj-radio-group-radio[data-checked] {
    box-shadow: inset 0 0 0 2px var(--hj-accent);
  }
  .hj-radio-group-radio[data-invalid]:not([data-checked]) {
    box-shadow: inset 0 0 0 1.5px var(--hj-danger);
  }
  .hj-radio-group-radio[data-disabled] {
    opacity: 0.4;
    cursor: not-allowed;
  }

  .hj-radio-group-indicator {
    display: block;
    width: 50%;
    height: 50%;
    border-radius: 50%;
    background: var(--hj-accent);
    transform: scale(0);
    /* leaving: fast */
    transition: transform var(--hj-dur-fast) var(--hj-ease-out);
  }
  /* The dot springs in — snappy, unclamped: a 4% overshoot reads as the press landing. */
  .hj-radio-group-indicator[data-checked] {
    transform: scale(1);
    transition: transform var(--hj-dur-snappy) var(--hj-ease-snappy);
  }
}

'use client';
import { Radio as BaseRadio } from '@base-ui/react/radio';
import { RadioGroup as BaseGroup } from '@base-ui/react/radio-group';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { elementPart, part } from '../../system/part.tsx';
import type { ElementPartProps, HanjiPart } from '../../system/part.tsx';
import { cls, withDefaults } from '../../system/slot.ts';

export interface RootOwnProps {
  /** Stack (default) or lay the options out in a row. */
  orientation?: 'vertical' | 'horizontal';
}
export interface RootProps extends RootOwnProps, React.ComponentProps<typeof BaseGroup> {}

/** Exactly one of a few options. Arrow keys move and select; Tab leaves the group. */
export function Root(props: RootProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    orientation = 'vertical',
    className,
    ...rest
  } = withDefaults(config, 'RadioGroup.Root', props);
  return (
    <BaseGroup
      {...rest}
      data-orientation={orientation}
      className={cls(config, 'RadioGroup.Root', 'hj-radio-group', className)}
    />
  );
}

/** One option row: a `<label>` with a Radio.Root and its text, so the whole row selects. */
export const Item: (props: ElementPartProps<'label'>) => React.ReactElement = elementPart(
  'label',
  'RadioGroup.Item',
  'hj-radio-group-item',
);

/** A help line under an Item's text. */
export const Description: (props: ElementPartProps<'span'>) => React.ReactElement = elementPart(
  'span',
  'RadioGroup.Description',
  'hj-radio-group-description',
);

/** The dot. Kept mounted so it can scale out as well as in. */
export const Indicator: HanjiPart<typeof BaseRadio.Indicator> = part(
  BaseRadio.Indicator,
  'Radio.Indicator',
  'hj-radio-group-indicator',
);

export interface RadioOwnProps {
  /** md = 22 (hanji), sm = 18. */
  size?: 'sm' | 'md';
}
export interface RadioProps extends RadioOwnProps, BaseRadio.Root.Props {}

/** The 22px ring. Renders its Indicator when childless, so `<Radio.Root value="x" />` is complete. */
export function Radio(props: RadioProps): React.ReactElement {
  const config = useHanjiConfig();
  const { size = 'md', className, children, ...rest } = withDefaults(config, 'Radio.Root', props);
  return (
    <BaseRadio.Root
      {...rest}
      data-size={size}
      className={cls(config, 'Radio.Root', 'hj-radio-group-radio', className)}
    >
      {children ?? <Indicator keepMounted />}
    </BaseRadio.Root>
  );
}
